if (points.size() <= 1) return points;

std::vector<Point2d> sorted_points = points;
std::sort(sorted_points.begin(), sorted_points.end(), [](const Point2d& a, const Point2d& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
});

std::vector<Point2d> hull;
hull.reserve(sorted_points.size() + 1);

for (int i = 0; i < 2; ++i) {
    int start = hull.size();
    for (const Point2d& p : sorted_points) {
        while (hull.size() >= start + 2) {
            Point2d a = hull[hull.size() - 2];
            Point2d b = hull.back();
            double cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
            if (cross < 0) break;
            if (cross == 0 && (b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y) >=
                              (p.x - a.x) * (p.x - a.x) + (p.y - a.y) * (p.y - a.y)) break;
            hull.pop_back();
        }
        hull.push_back(p);
    }
    hull.pop_back();
    std::reverse(sorted_points.begin(), sorted_points.end());
}

return hull;
// END_CODE

